function flowerGame(n, m) {
  // Alice wins exactly when x + y is odd: one of x, y is odd and the other even.
  const oddX = Math.ceil(n / 2);
  const evenX = Math.floor(n / 2);
  const oddY = Math.ceil(m / 2);
  const evenY = Math.floor(m / 2);
  const oddXEvenY = oddX * evenY;
  const evenXOddY = evenX * oddY;
  return oddXEvenY + evenXOddY;
}

