function flowerGame(n, m) {
  // Play the game out: wins[a][b] says whether the player to move wins with a and b flowers left.
  const wins = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(false));
  for (let a = 0; a <= n; a++) {
    for (let b = 0; b <= m; b++) {
      if (a > 0 && !wins[a - 1][b]) wins[a][b] = true;
      if (b > 0 && !wins[a][b - 1]) wins[a][b] = true;
    }
  }
  let count = 0;
  for (let x = 1; x <= n; x++) for (let y = 1; y <= m; y++) if (wins[x][y]) count++;
  return count;
}

